/**
 * Importer for the export produced by Apple's Journal app
 * (Journal → Settings → Export, iOS 18+). The export is a folder:
 *
 *   AppleJournalEntries/
 *     index.html                  list of entries, newest first
 *     Entries/<date>_<title>.html one page per entry
 *     Resources/<UUID>.<ext>      photos (HEIC/JPEG), videos (MOV), map snapshots
 *     Resources/<UUID>.json       metadata: {"date": <Apple epoch secs>, "placeName": ..., "visits": [...]}
 *
 * Entry pages are generated by "Cocoa HTML Writer" and are not well-formed
 * (divs inside <p><span>), so the structural parts are pulled out with
 * patterns and only the body paragraphs go through DOMParser.
 */
import JSZip from 'jszip';
import { db, defaultJournalId, newId, type Entry, type Media, type MediaKind, type Place } from '../db';
import { makePoster } from '../poster';

/** Seconds between 1970-01-01 and Apple's reference date 2001-01-01. */
const APPLE_EPOCH_OFFSET = 978307200;

export interface ImportSource {
  paths: string[];
  read(path: string): Promise<Blob>;
  readText(path: string): Promise<string>;
}

export interface ImportProgress {
  done: number;
  total: number;
  message: string;
}

export interface ImportResult {
  imported: number;
  skipped: number;
  media: number;
  warnings: string[];
}

export async function sourceFromZip(file: Blob): Promise<ImportSource> {
  const zip = await JSZip.loadAsync(file);
  const paths = Object.keys(zip.files).filter((p) => !zip.files[p].dir && !p.startsWith('__MACOSX/'));
  return {
    paths,
    read: async (p) => zip.file(p)!.async('blob'),
    readText: async (p) => zip.file(p)!.async('string'),
  };
}

/** For a folder picked with <input webkitdirectory> or dropped files. */
export function sourceFromFiles(files: File[]): ImportSource {
  const byPath = new Map(files.map((f) => [f.webkitRelativePath || f.name, f] as const));
  return {
    paths: [...byPath.keys()],
    read: async (p) => byPath.get(p)!,
    readText: async (p) => byPath.get(p)!.text(),
  };
}

export interface ParsedAsset {
  gridId: string;
  type: string;
  file?: string;
  caption?: string;
}

export interface ParsedEntry {
  fileName: string;
  date: Date | null;
  title: string;
  body: string;
  assets: ParsedAsset[];
}

const decode = (s: string) => {
  const el = document.createElement('textarea');
  el.innerHTML = s;
  return el.value;
};

const clean = (s: string) => s.replace(/ /g, ' ').replace(/[ \t]+$/gm, '');

export function parseEntryHtml(fileName: string, html: string): ParsedEntry {
  const header = /<div class="pageHeader">([\s\S]*?)<\/div>/.exec(html)?.[1]?.trim() ?? '';
  // "Saturday, August 31, 2024" → drop the weekday and parse.
  const dateText = header.replace(/^[A-Za-z]+,\s*/, '');
  const parsed = Date.parse(dateText);
  let date: Date | null = Number.isNaN(parsed) ? null : new Date(parsed);
  if (!date) {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(fileName);
    if (m) date = new Date(+m[1], +m[2] - 1, +m[3]);
  }

  const titleMatch = /<div class='title'>([\s\S]*?)<\/div>/.exec(html);
  const title = titleMatch ? clean(decode(titleMatch[1].replace(/<[^>]+>/g, ''))).trim() : '';

  const gridStart = html.indexOf('<div class="assetGrid">');
  const gridEnd = titleMatch ? titleMatch.index : -1;
  const assets: ParsedAsset[] = [];
  if (gridStart >= 0 && gridEnd > gridStart) {
    const grid = html.slice(gridStart, gridEnd);
    const itemRe = /<div id="([^"]+)" class="gridItem assetType_(\w+)[^"]*"/g;
    const starts: { id: string; type: string; at: number }[] = [];
    for (let m; (m = itemRe.exec(grid)); ) starts.push({ id: m[1], type: m[2], at: m.index });
    starts.forEach((s, i) => {
      const chunk = grid.slice(s.at, starts[i + 1]?.at ?? grid.length);
      const file = /src="(?:\.\.\/)?Resources\/([^"]+)"/.exec(chunk)?.[1];
      const captionHtml = /<div class="gridItemOverlayFooter"[^>]*>([\s\S]*?)<\/div>/.exec(chunk)?.[1];
      assets.push({
        gridId: s.id,
        type: s.type,
        file: file ? decodeURIComponent(file) : undefined,
        caption: captionHtml ? decode(captionHtml.replace(/<[^>]+>/g, '')).trim() || undefined : undefined,
      });
    });
  }

  let body = '';
  const bodyStart = html.indexOf("<div class='bodyText'>");
  if (bodyStart >= 0) {
    const doc = new DOMParser().parseFromString(
      html.slice(bodyStart + "<div class='bodyText'>".length),
      'text/html'
    );
    const lines = [...doc.querySelectorAll('p')].map((p) => clean(p.textContent ?? '').trim());
    body = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  }

  return { fileName, date, title, body, assets };
}

/**
 * Day + title, ignoring case and spacing. Untitled entries also compare the
 * start of the text, so two untitled entries on the same day are not merged.
 */
export function duplicateKey(e: Pick<Entry, 'date' | 'title' | 'body'>): string {
  const d = new Date(e.date);
  const norm = (s: string) => s.toLowerCase().replace(/\s+/g, ' ').trim();
  const title = norm(e.title);
  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}|${title || 'untitled:' + norm(e.body).slice(0, 80)}`;
}

/** Entry file names in the order index.html lists them (newest first). */
export function parseIndexOrder(html: string): string[] {
  return [...html.matchAll(/href="Entries\/([^"]+)"/g)].map((m) => decodeURIComponent(m[1]));
}

function kindFor(type: string, file: string): MediaKind | null {
  const t = type.toLowerCase();
  if (t === 'photo' || t === 'livephoto') return 'photo';
  if (t === 'video') return 'video';
  if (t === 'audio') return 'audio';
  if (t.includes('map')) return 'map';
  const ext = file.split('.').pop()!.toLowerCase();
  if (['heic', 'heif', 'jpg', 'jpeg', 'png', 'gif', 'webp'].includes(ext)) return 'photo';
  if (['mov', 'mp4', 'm4v'].includes(ext)) return 'video';
  if (['m4a', 'mp3', 'wav', 'aac', 'caf'].includes(ext)) return 'audio';
  return null;
}

const MIME: Record<string, string> = {
  jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp',
  heic: 'image/heic', heif: 'image/heif',
  // Browsers on Windows play H.264 .mov files when they are labelled as mp4.
  mov: 'video/mp4', mp4: 'video/mp4', m4v: 'video/mp4',
  m4a: 'audio/mp4', mp3: 'audio/mpeg', wav: 'audio/wav', aac: 'audio/aac',
};

/** True when the bytes are HEIC/HEIF, whatever the file extension says (iPhones save some HEIC as .jpeg). */
export async function isHeic(blob: Blob): Promise<boolean> {
  const head = new TextDecoder().decode(await blob.slice(4, 12).arrayBuffer());
  return /^ftyp(heic|heix|heim|heis|hevc|hevx|mif1|msf1)/.test(head);
}

/** HEIC is only viewable in Safari, so convert it to JPEG. */
export async function heicToJpeg(blob: Blob): Promise<Blob> {
  const { default: heic2any } = await import('heic2any');
  const out = await heic2any({ blob, toType: 'image/jpeg', quality: 0.92 });
  return Array.isArray(out) ? out[0] : out;
}

async function toViewable(blob: Blob, kind: MediaKind): Promise<Blob> {
  if ((kind === 'photo' || kind === 'map') && (await isHeic(blob))) return heicToJpeg(blob);
  return blob;
}

interface ResourceMeta {
  date?: number;
  placeName?: string;
  visits?: { placeName?: string; city?: string; latitude?: number; longitude?: number }[];
}

function placeFrom(meta: ResourceMeta | undefined): Place | undefined {
  const v = meta?.visits?.[0];
  if (v) {
    const name = [v.placeName, v.city].filter(Boolean).join(', ');
    return { name: name || 'Unknown place', lat: v.latitude, lng: v.longitude };
  }
  return meta?.placeName ? { name: meta.placeName } : undefined;
}

export async function importAppleJournal(
  src: ImportSource,
  onProgress: (p: ImportProgress) => void = () => {},
  journalId?: string
): Promise<ImportResult> {
  const targetJournal = journalId ?? (await defaultJournalId());
  const entryPaths = src.paths.filter((p) => /(^|\/)Entries\/[^/]+\.html?$/i.test(p));
  if (entryPaths.length === 0) {
    throw new Error(
      'No journal entries found. Choose the .zip of the AppleJournalEntries folder (it contains an "Entries" folder).'
    );
  }
  const root = entryPaths[0].replace(/Entries\/[^/]+$/i, '');
  const has = new Set(src.paths);
  const resourcePath = (name: string) => `${root}Resources/${name}`;

  let order: string[] = [];
  if (has.has(`${root}index.html`)) order = parseIndexOrder(await src.readText(`${root}index.html`));

  const result: ImportResult = { imported: 0, skipped: 0, media: 0, warnings: [] };
  // An entry already in the chosen journal with the same day and title is
  // treated as a duplicate, whether it was imported or typed in by hand.
  // Entries in other journals don't count, so the same export can be imported
  // into a second journal and the entries land where you picked.
  const existing = await db.entries.where('journalId').equals(targetJournal).toArray();
  const seen = new Set(existing.map(duplicateKey));
  const seenSources = new Set(existing.map((e) => e.sourceKey).filter(Boolean));
  const total = entryPaths.length;

  for (let i = 0; i < entryPaths.length; i++) {
    const path = entryPaths[i];
    const fileName = path.split('/').pop()!;
    onProgress({ done: i, total, message: `Importing ${fileName.replace(/\.html?$/, '').replace(/_/g, ' ')}` });

    const sourceKey = `apple-journal:${fileName}`;
    if (seenSources.has(sourceKey)) {
      result.skipped++;
      continue;
    }

    const parsed = parseEntryHtml(fileName, await src.readText(path));
    const dupKey = duplicateKey({ date: (parsed.date ?? new Date()).getTime(), title: parsed.title, body: parsed.body });
    if (seen.has(dupKey)) {
      result.skipped++;
      continue;
    }
    seen.add(dupKey);
    const entryId = newId();
    const media: Media[] = [];
    let mood: string | undefined;
    let entryPlace: Place | undefined;

    for (const a of parsed.assets) {
      if (a.type.toLowerCase() === 'stateofmind') {
        mood = a.caption ?? mood;
        continue;
      }
      let meta: ResourceMeta | undefined;
      const metaPaths = [a.gridId, a.file?.replace(/\.[^.]+$/, '')]
        .filter(Boolean)
        .map((n) => resourcePath(`${n}.json`));
      for (const mp of metaPaths) {
        if (has.has(mp)) {
          try {
            meta = JSON.parse(await src.readText(mp));
          } catch {
            /* ignore malformed metadata */
          }
          break;
        }
      }
      const place = placeFrom(meta);
      if (a.type.toLowerCase().includes('map') || meta?.visits) entryPlace ??= place;

      if (!a.file || !has.has(resourcePath(a.file))) {
        if (a.file) result.warnings.push(`${fileName}: missing file ${a.file}`);
        continue;
      }
      const kind = kindFor(a.type, a.file);
      if (!kind) {
        result.warnings.push(`${fileName}: skipped unsupported ${a.type} attachment`);
        continue;
      }
      const ext = a.file.split('.').pop()!.toLowerCase();
      let blob = await src.read(resourcePath(a.file));
      blob = new Blob([blob], { type: MIME[ext] ?? blob.type });
      try {
        blob = await toViewable(blob, kind);
      } catch {
        result.warnings.push(`${fileName}: could not convert ${a.file} to JPEG, kept the original`);
      }
      media.push({
        id: newId(),
        entryId,
        kind,
        blob,
        poster: kind === 'video' ? await makePoster(blob, 8000).catch(() => undefined) : undefined,
        caption: a.caption,
        takenAt: meta?.date != null ? (meta.date + APPLE_EPOCH_OFFSET) * 1000 : undefined,
        place,
      });
    }
    entryPlace ??= media.find((m) => m.place)?.place;

    // Pages only carry the day, so date entries at noon and keep the
    // index.html order for entries that share a day.
    const day = parsed.date ?? new Date();
    const rank = order.indexOf(fileName);
    const date = new Date(day.getFullYear(), day.getMonth(), day.getDate(), 12).getTime() +
      (rank >= 0 ? (order.length - rank) * 1000 : 0);

    const now = Date.now();
    const entry: Entry = {
      id: entryId,
      journalId: targetJournal,
      date,
      title: parsed.title,
      body: parsed.body,
      bookmarked: false,
      mood,
      place: entryPlace,
      mediaIds: media.map((m) => m.id),
      sourceKey,
      createdAt: now,
      updatedAt: now,
    };
    await db.transaction('rw', db.entries, db.media, async () => {
      await db.media.bulkAdd(media);
      await db.entries.add(entry);
    });
    result.imported++;
    result.media += media.length;
  }
  onProgress({ done: total, total, message: 'Done' });
  return result;
}
